/**
 * Typed access to the MyGo runtime, which MyGo injects into every page of
 * an app as `window.mygo`. The client that `mygo generate` writes for your Go
 * services is built on it; use it directly for window controls and the
 * platform:
 *
 * ```ts
 * import { currentWindow, runtime } from "mygo-runtime";
 *
 * if (runtime().platform === "darwin") document.body.classList.add("mac");
 * await currentWindow.toggleMaximize();
 * ```
 *
 * @module
 */
import type {
  Channel as ChannelType,
  Direction,
  LocaleChange,
  Runtime,
  ThemePreferences,
  WindowControls,
} from "./types";

export type { Direction, LocaleChange, Platform, Runtime, ThemePreferences, WindowControls } from "./types";

declare global {
  interface Window {
    /** The MyGo runtime; missing outside MyGo windows. */
    mygo?: Runtime;
  }
}

/** Reports whether the page runs inside a MyGo window. */
export function isMyGo(): boolean {
  return typeof globalThis === "object" && (globalThis as { mygo?: Runtime }).mygo !== undefined;
}

/**
 * Returns the MyGo runtime. Throws when the page is not running inside a
 * MyGo window, e.g. when the dev server is opened in a regular browser.
 */
export function runtime(): Runtime {
  const rt = (globalThis as { mygo?: Runtime }).mygo;
  if (!rt) throw new Error("mygo: runtime not found; is this page running inside a MyGo window?");
  return rt;
}

/**
 * Calls a bound Go method by name, e.g. `call("Greeter.Greet", "Ada")`.
 * Prefer the typed client generated by `mygo generate`. A Go error rejects
 * with a {@link CallError}.
 */
export function call<T = unknown>(method: string, ...args: unknown[]): Promise<T> {
  try {
    return runtime().call<T>(method, ...args);
  } catch (err) {
    return Promise.reject(err);
  }
}

/**
 * A stream of values from a Go method that takes a `*mygo.Channel[T]`.
 * Create one, pass it to the call in place of that parameter, and iterate
 * it or handle its values with `onmessage`:
 *
 * ```ts
 * const lines = new Channel<string>();
 * const done = Shell.tail("ping -c 3 example.com", lines);
 * for await (const line of lines) output.append(line + "\n");
 * await done;
 * ```
 *
 * It closes when the method returns; `close()`, or breaking out of the
 * loop, stops the method. A channel serves one call.
 */
export type Channel<T = unknown> = ChannelType<T>;

/** Creates a {@link Channel}, optionally with its `onmessage` handler. */
export const Channel = function <T>(onmessage?: (value: T) => void): Channel<T> {
  return runtime().channel<T>(onmessage);
} as unknown as new <T = unknown>(onmessage?: (value: T) => void) => Channel<T>;

/** Subscribes to a Go event by name. Returns a function that unsubscribes. */
export function on<T = unknown>(name: string, listener: (payload: T) => void): () => void {
  return runtime().on<T>(name, listener);
}

/** Like {@link on}, but unsubscribes after the first event. */
export function once<T = unknown>(name: string, listener: (payload: T) => void): () => void {
  return runtime().once<T>(name, listener);
}

/**
 * The language the app shows, a BCP 47 tag such as "en" or "zh-Hans"
 * (`App.Locale`): the page has it from document start, so its first paint
 * can be in it.
 *
 * ```ts
 * document.documentElement.lang = locale();
 * document.documentElement.dir = direction();
 * ```
 */
export function locale(): string {
  return runtime().locale;
}

/** The direction the language the app shows is written in: "ltr" or "rtl". */
export function direction(): Direction {
  return runtime().dir;
}

/**
 * Subscribes to changes of the language the app shows, as `App.SetLocale`
 * makes them, or the user's languages while the app follows them. The
 * listener hears only of a language the page did not have: a page loaded
 * after a change starts with the new one. Returns a function that
 * unsubscribes.
 *
 * ```ts
 * onLocaleChange((tag, dir) => {
 *   document.documentElement.lang = tag;
 *   document.documentElement.dir = dir;
 * });
 * ```
 */
export function onLocaleChange(listener: (locale: string, dir: Direction) => void): () => void {
  return on<LocaleChange>("mygo:locale", (p) => listener(p.locale, p.dir));
}

/** A typed event sent by the Go side, declared with `mygo.NewEvent`. */
export interface GoEvent<T> {
  readonly name: string;
  /** Subscribes to the event and returns a function that unsubscribes. */
  on(listener: (payload: T) => void): () => void;
  /** Like on, but unsubscribes after the first event. */
  once(listener: (payload: T) => void): () => void;
}

/** Returns the typed event `name`; the generated client declares them. */
export function event<T>(name: string): GoEvent<T> {
  return {
    name,
    on: (listener) => on<T>(name, listener),
    once: (listener) => once<T>(name, listener),
  };
}

/** The error of a call whose Go method returned an error. */
export interface CallError extends Error {
  readonly name: "CallError";
  /** The method that failed, e.g. "Greeter.Greet". */
  readonly method: string;
}

/** Reports whether err comes from a Go method that returned an error. */
export function isCallError(err: unknown): err is CallError {
  return err instanceof Error && err.name === "CallError";
}

/** Files dropped on the window, e.g. from Finder or Explorer. */
export interface FileDrop {
  /** Absolute paths of the dropped files and directories. */
  paths: string[];
  /** Where they were dropped, in CSS pixels, like `clientX`. */
  x: number;
  /** Where they were dropped, in CSS pixels, like `clientY`. */
  y: number;
}

/**
 * Subscribes to files dropped on the window, with their paths, which DOM
 * drop events do not tell. Only the app's own pages get them. Returns a
 * function that unsubscribes.
 *
 * ```ts
 * onFileDrop(({ paths, x, y }) => {
 *   const target = document.elementFromPoint(x, y);
 * });
 * ```
 */
export function onFileDrop(listener: (drop: FileDrop) => void): () => void {
  return on<FileDrop>("mygo:file-drop", listener);
}

/** The document a window shows (mygo.NewDocuments), as Go describes it. */
export interface DocumentState {
  /** The file name, or a name such as "Untitled 2" while untitled. */
  name: string;
  /** The file, "" while the document is untitled. */
  path: string;
  /** Whether the document has unsaved changes. */
  edited: boolean;
  /** Whether its file can't be written: saving asks for another. */
  readOnly: boolean;
  /** Whether another app changed its file while it had unsaved changes. */
  conflict: boolean;
  /** Whether its file was deleted: saving writes it again. */
  deleted: boolean;
}

/**
 * Subscribes to the state of the window's document: edited, saved,
 * renamed, moved, changed by another app. Only the app's own pages get it.
 * Returns a function that unsubscribes.
 *
 * ```ts
 * onDocumentState(({ name, edited }) => {
 *   heading.textContent = edited ? `${name} (edited)` : name;
 * });
 * ```
 */
export function onDocumentState(listener: (state: DocumentState) => void): () => void {
  return on<DocumentState>("mygo:document-state", listener);
}

/**
 * Subscribes to the window's document being read from its file again:
 * reverted, or changed by another app while it had no unsaved changes.
 * Fetch its content again, with the service bound to
 * `Documents.Service()`. Returns a function that unsubscribes.
 */
export function onDocumentReload(listener: () => void): () => void {
  return on<unknown>("mygo:document-reload", () => listener());
}

/**
 * Returns the accent color and the accessibility settings of the desktop
 * (`mygo.Theme.Preferences()` in Go), current from document start on.
 * Throws outside MyGo, as {@link runtime} does.
 *
 * ```ts
 * const { accent, reduceTransparency } = preferences();
 * ```
 *
 * CSS gets the accent and the text scale from the `--mygo-accent` and
 * `--mygo-text-scale` variables of `:root`.
 */
export function preferences(): ThemePreferences {
  return runtime().preferences;
}

/**
 * Subscribes to changes of the desktop's preferences, which
 * {@link preferences} returns; the listener gets the new ones. Returns a
 * function that unsubscribes.
 *
 * ```ts
 * const apply = (p: ThemePreferences) => root.classList.toggle("opaque", p.reduceTransparency);
 * apply(preferences());
 * onPreferences(apply);
 * ```
 */
export function onPreferences(listener: (preferences: ThemePreferences) => void): () => void {
  return on<ThemePreferences>("mygo:preferences", listener);
}

/** The window hosting the page, e.g. for a custom title bar. */
export const currentWindow: WindowControls = {
  minimize: async () => runtime().window.minimize(),
  maximize: async () => runtime().window.maximize(),
  unmaximize: async () => runtime().window.unmaximize(),
  toggleMaximize: async () => runtime().window.toggleMaximize(),
  isMaximized: async () => runtime().window.isMaximized(),
  toggleFullScreen: async () => runtime().window.toggleFullScreen(),
  close: async () => runtime().window.close(),
  setTitle: async (title) => runtime().window.setTitle(title),
};
